import { useEffect, useMemo, useState } from 'react';
import { Activity, Archive, Bell, BookOpen, CalendarDays, ChartNoAxesCombined, ChevronDown, CircleHelp, ClipboardList, Dumbbell, FileText, Filter, HeartPulse, Image, LayoutDashboard, LogOut, Menu, Newspaper, Plus, Search, Shield, Trophy, Users, Video, X } from 'lucide-react';
import { api, download, getAll } from './api';

const nav = [
  { label: 'Overview', icon: LayoutDashboard, items: ['Dashboard'] },
  { label: 'Manage', icon: Users, items: ['Players', 'Seasons', 'Matches', 'Training', 'Tournaments', 'Team events'] },
  { label: 'Analyze', icon: ChartNoAxesCombined, items: ['Performance', 'Post-match analysis', 'Reports', 'Injury & welfare'] },
  { label: 'Learn', icon: BookOpen, items: ['Rules & laws', 'Tactical learning', 'Video resources'] },
  { label: 'Connect', icon: Bell, items: ['News & information', 'Announcements', 'Media gallery', 'Alumni & supporters'] },
  { label: 'Preserve', icon: Archive, items: ['Historical archive'] },
  { label: 'Administration', icon: Shield, items: ['Account management'] },
];

function App() {
  const [page, setPage] = useState('Dashboard');
  const [user, setUser] = useState('');
  const [token, setToken] = useState(() => localStorage.getItem('wazimbaToken'));
  const [role, setRole] = useState('member');
  const [designation, setDesignation] = useState('');
  const [canAccessWelfare, setCanAccessWelfare] = useState(false);
  const [authReady, setAuthReady] = useState(!localStorage.getItem('wazimbaToken'));
  const isStaff = role === 'staff' || role === 'administrator';
  const isAdmin = role === 'administrator';
  const [data, setData] = useState({});
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [query, setQuery] = useState('');
  const [mobileNav, setMobileNav] = useState(false);
  const [modal, setModal] = useState(false);
  const [activeRecord, setActiveRecord] = useState(null);
  const [modalPage, setModalPage] = useState('');

  const refresh = async () => {
    setLoading(true); setError('');
    const specs = { players: '/players/', matches: '/matches/', training: '/training-sessions/', tournaments: '/tournaments/', announcements: '/announcements/', news: '/news/', seasons: '/seasons/', registrations: '/season-registrations/', events: '/team-events/', eventAttendance: '/team-event-attendance/', learning: '/learning-resources/', media: '/media/', alumni: '/alumni/', reviews: '/match-reviews/', participations: '/match-participations/', attendance: '/training-attendance/', ...(canAccessWelfare ? { injuries: '/injury-records/' } : {}) };
    const failures = [];
    const entries = await Promise.all(Object.entries(specs).map(async ([key, path]) => {
      try { return [key, await getAll(path)]; } catch (e) { failures.push(`${key}: ${e.message}`); return [key, []]; }
    }));
    try { const dashboard = await api('/dashboard/'); entries.push(['dashboard', dashboard]); } catch (e) { failures.push(`dashboard: ${e.message}`); }
    setData(Object.fromEntries(entries));
    setError(failures.length ? `Could not load ${failures.join('; ')}` : '');
    setLoading(false);
  };

  useEffect(() => {
    if (!token) { setAuthReady(true); return; }
    let active = true; setAuthReady(false);
    api('/auth/me/').then(me => { if (!active) return; setUser(me.name || me.username); setRole(me.role || 'member'); setDesignation(me.designation || ''); setCanAccessWelfare(Boolean(me.can_access_welfare)); setAuthReady(true); })
      .catch(() => { if (!active) return; localStorage.removeItem('wazimbaToken'); localStorage.removeItem('wazimbaUser'); localStorage.removeItem('wazimbaStaff'); setToken(null); setAuthReady(true); });
    return () => { active = false; };
  }, [token]);
  useEffect(() => { if (token && authReady) refresh(); }, [token, authReady]);

const logout = async () => {
  try {
    await api('/auth/logout/', { method: 'POST' });
  } catch (error) {
    console.error('Server logout failed:', error);
  } finally {
    localStorage.removeItem('wazimbaToken');
    localStorage.removeItem('wazimbaUser');
    localStorage.removeItem('wazimbaStaff');
    setToken(null);
    setRole('member'); setDesignation(''); setCanAccessWelfare(false); setUser('');
  }
};

  if (!token) return <Login onLogin={t => { localStorage.setItem('wazimbaToken', t); localStorage.removeItem('wazimbaUser'); localStorage.removeItem('wazimbaStaff'); setToken(t); setAuthReady(false); }} />;
  if (!authReady) return <div className="login-screen"><div className="panel empty-panel">Checking your Wazimba account…</div></div>;
  const active = nav.find(section => section.items.includes(page));

  return <div className="app-shell">
    <aside className={`sidebar ${mobileNav ? 'open' : ''}`}>
      <div className="brand"><div className="brand-mark">W</div><div><strong>WAZIMBA</strong><small>RUGBY 7s</small></div><button className="icon-button mobile-close" onClick={() => setMobileNav(false)}><X size={18}/></button></div>
      <div className="club-label">TEAM MANAGEMENT</div>
      <nav>{nav.filter(section => section.label !== 'Administration' || isAdmin).map(section => <div className="nav-section" key={section.label}><div className="nav-heading"><section.icon size={14}/>{section.label}</div>{section.items.filter(item => item !== 'Injury & welfare' || canAccessWelfare).map(item => <button key={item} className={`nav-item ${page === item ? 'selected' : ''}`} onClick={() => { setPage(item); setMobileNav(false); }}><span className="nav-dot"/>{item}</button>)}</div>)}</nav>
      <div className="sidebar-bottom"><div className="season-chip"><span className="live-dot"/>2026 Season <ChevronDown size={14}/></div><div className="sidebar-footer">Wazimba Rugby 7s<br/><span>Built for today. Preserving for tomorrow.</span></div></div>
    </aside>
    {mobileNav && <button className="scrim" onClick={() => setMobileNav(false)} aria-label="Close menu"/>}
    <main className="main-area">
      <header className="topbar"><div className="top-left"><button className="icon-button hamburger" onClick={() => setMobileNav(true)}><Menu/></button><div className="breadcrumbs">Wazimba <span>/</span> {active?.label || 'System'} <span>/</span> <b>{page}</b></div></div><div className="top-actions"><label className="top-search"><Search size={16}/><input placeholder="Search players, matches..." value={query} onChange={e => setQuery(e.target.value)} onKeyDown={e=>{if(e.key==='Enter'){const term=query.trim().toLowerCase();setPage(term&&(data.matches||[]).some(m=>JSON.stringify(m).toLowerCase().includes(term))?'Matches':'Players');}}}/><kbd>⌘ K</kbd></label><button className="icon-button notification" title="Announcements" onClick={() => setPage('Announcements')}><Bell size={19}/></button><div className="user-menu"><div className="avatar">{user.split(' ').map(x => x[0]).slice(0,2).join('')}</div><div><b>{user}</b><small>{designation || (role === 'administrator' ? 'Administrator' : role === 'staff' ? 'Team staff' : 'Team member')}</small></div></div><button className="icon-button logout" onClick={logout} title="Log out"><LogOut size={17}/></button></div></header>
      <div className="page-content"><div className="page-heading"><div><div className="eyebrow">{page === 'Dashboard' ? new Intl.DateTimeFormat('en-GB',{weekday:'long',day:'numeric',month:'long',year:'numeric',timeZone:'Africa/Nairobi'}).format(new Date()).toUpperCase() : active?.label?.toUpperCase()}</div><h1>{page === 'Dashboard' ? `Good morning, ${user.split(' ')[0]}.` : page}</h1><p>{page === 'Dashboard' ? (role === 'administrator' ? 'System overview and team activity.' : role === 'staff' ? 'Team operations, performance and upcoming commitments.' : 'Your squad updates, performance and upcoming commitments.') : descriptions[page] || `Manage and review your team's ${page.toLowerCase()}.`}</p></div>{isStaff && canCreate(page) && <button className="primary-button" onClick={() => { setModalPage(page==='News & information'?'News article':page); setActiveRecord(null); setModal(true); }}><Plus size={17}/>{createLabel(page)}</button>}</div>
        {error && <div className="notice warning"><Shield size={16}/>{error} <button className="text-button" onClick={refresh}>Retry</button></div>}
        {page === 'Account management' ? <AccountManagement/> : page === 'Dashboard' ? <Dashboard data={data} loading={loading} onOpen={setPage} role={role}/> : ['Performance','Reports'].includes(page) ? <PerformanceSection seasons={data.seasons || []} initialTab={page === 'Reports' ? 'reports' : 'team'}/> : page === 'Post-match analysis' ? <ReviewSection matches={data.matches || []} reviews={data.reviews || []} isStaff={isStaff} onChanged={refresh} onCreate={matchId => { setModalPage('Match review'); setActiveRecord({match:matchId}); setModal(true); }} onEdit={record => { setModalPage('Match review'); setActiveRecord(record); setModal(true); }}/> : <SectionPage page={page} data={data} query={query} onQuery={setQuery} loading={loading} isStaff={isStaff} canAccessWelfare={canAccessWelfare} onOpen={setPage} onCreate={(type, record=null) => { setModalPage(type==='News & information'?'News article':type); setActiveRecord(record); setModal(true); }} onEdit={(type, record) => { setModalPage(type==='News & information'?'News article':type); setActiveRecord(record); setModal(true); }} onChanged={refresh} />}
      </div>
      <footer className="footer"><span>© 2026 Wazimba Rugby 7s</span><span>Manage · Analyze · Learn · Connect · Preserve</span></footer>
    </main>
    {modal && <CreateModal page={modalPage || page} seasons={data.seasons || []} tournaments={data.tournaments || []} matches={data.matches || []} training={data.training || []} events={data.events || []} players={data.players || []} record={activeRecord} onClose={() => { setModal(false); setActiveRecord(null); }} onSaved={() => { setModal(false); setActiveRecord(null); refresh(); }}/>}
  </div>;
}

const descriptions = { Players: 'Manage player profiles, availability and squad participation.', Matches: 'Plan fixtures and keep a connected record of every match.', Training: 'Schedule sessions, set objectives and track attendance.', Tournaments: 'Track upcoming, ongoing and completed competitions.', Announcements: 'Share the team’s official updates in one place.', Seasons: 'Organize squads, fixtures and achievements by season.', Performance: 'Review match and player performance as your records grow.', 'Post-match analysis': 'Turn match observations into lessons and training objectives.', 'Rules & laws': 'A home for Rugby 7s laws, explanations and official references.', 'Tactical learning': 'Build team knowledge with drills, tactics and game situations.', 'Video resources': 'Collect authorized external resources and Wazimba learning media.', 'News & information': 'Keep relevant rugby updates and source links together.', 'Injury & welfare': 'Track availability and welfare records with restricted access.', 'Historical archive': 'Preserve seasons, results, achievements and team stories.', 'Media gallery': 'Browse team media by season, match, training or event.', 'Team events': 'Coordinate meetings, bonding, welfare and team activities.', 'Alumni & supporters': 'Keep the Wazimba community connected with consent.' };

function Login({ onLogin }) {
  const [mode, setMode] = useState(() => new URLSearchParams(window.location.search).has('reset') ? 'confirm' : 'login');
  const [username, setUsername] = useState(''); const [fullName, setFullName] = useState(''); const [email, setEmail] = useState('');
  const [password, setPassword] = useState(''); const [confirmation, setConfirmation] = useState('');
  const [acceptedTerms, setAcceptedTerms] = useState(false); const [error, setError] = useState(''); const [message, setMessage] = useState(''); const [busy, setBusy] = useState(false);
  const submit = async e => {
    e.preventDefault(); setBusy(true); setError(''); setMessage('');
    try {
      if (mode === 'register') {
        await api('/auth/register/', { method: 'POST', body: JSON.stringify({ username, full_name: fullName, email, password, password_confirmation: confirmation, accepted_terms: acceptedTerms }) });
        setMessage('Account created as a member. You can sign in now.'); setMode('login');
      } else if (mode === 'reset') {
        await api('/auth/password-reset/', { method: 'POST', body: JSON.stringify({ email }) });
        setMessage('If an account uses that email, reset instructions have been sent.');
      } else if (mode === 'confirm') {
        if(password!==confirmation) throw new Error('Passwords do not match.');
        const params=new URLSearchParams(window.location.search);
        await api('/auth/password-reset/confirm/',{method:'POST',body:JSON.stringify({uid:params.get('uid'),token:params.get('token'),password})});
        window.history.replaceState({},'',window.location.pathname); setMessage('Password changed. Sign in using your new password.'); setPassword(''); setConfirmation(''); setMode('login');
      } else {
        const result = await api('/auth/token/', { method: 'POST', body: JSON.stringify({ username, password }) }); onLogin(result.token);
      }
    } catch (err) { setError(err.message === 'Request failed (404)' ? 'The API is not running yet. Start the Django backend, then try again.' : err.message); }
    finally { setBusy(false); }
  };
  return <div className="login-screen"><div className="login-art"><div className="login-brand"><div className="brand-mark large">W</div><div><strong>WAZIMBA</strong><small>RUGBY 7s</small></div></div><div className="art-copy"><span>LAIKIPIA UNIVERSITY · RUGBY</span><h1>One team.<br/>One standard.</h1><p>Manage · Analyze · Learn · Connect · Preserve</p></div><div className="art-footer">WAZIMBA RUGBY 7s <span>NAIROBI, KENYA</span></div></div>
    <form className="login-form" onSubmit={submit}><div className="login-mobile-brand"><div className="brand-mark">W</div><strong>WAZIMBA RUGBY 7s</strong></div><div className="eyebrow">TEAM PORTAL</div><h2>{mode === 'register' ? 'Create a member account' : mode === 'reset' || mode === 'confirm' ? 'Reset your password' : 'Welcome back'}</h2><p>{mode === 'login' ? 'Sign in to your Wazimba account.' : mode === 'register' ? 'Public registrations receive member access only.' : mode==='confirm' ? 'Choose a new password for your account.' : 'We will email a secure, expiring reset link if the account exists.'}</p>
      {error && <div className="form-error">{error}</div>}{message && <div className="notice">{message}</div>}
      {mode === 'register' && <label>Full name<input required value={fullName} onChange={e=>setFullName(e.target.value)}/></label>}
      {!['reset','confirm'].includes(mode) && <label>Username<input required autoComplete="username" value={username} onChange={e=>setUsername(e.target.value)} placeholder="Your username"/></label>}
      {(mode === 'register' || mode === 'reset') && <label>Email<input required type="email" autoComplete="email" value={email} onChange={e=>setEmail(e.target.value)}/></label>}
      {mode !== 'reset' && <label>Password<input required type="password" autoComplete={mode==='login'?'current-password':'new-password'} value={password} onChange={e=>setPassword(e.target.value)} placeholder="Your password"/></label>}
      {mode === 'register' && <><label>Confirm password<input required type="password" autoComplete="new-password" value={confirmation} onChange={e=>setConfirmation(e.target.value)}/></label><label className="terms-check"><input type="checkbox" checked={acceptedTerms} onChange={e=>setAcceptedTerms(e.target.checked)}/> I agree to the team account and privacy terms.</label></>}
      {mode==='confirm'&&<label>Confirm new password<input required type="password" value={confirmation} onChange={e=>setConfirmation(e.target.value)}/></label>}<button className="primary-button sign-in" disabled={busy}>{busy ? 'Please wait…' : mode==='login'?'Sign in':mode==='register'?'Create member account':mode==='confirm'?'Change password':'Send reset link'}</button>
      <div className="login-foot"><Shield size={14}/> Access is assigned and verified by Wazimba.</div>
      <div className="login-links">{mode==='login' ? <><button type="button" className="text-button" onClick={()=>{setMode('register');setError('');setMessage('');}}>Create account</button><button type="button" className="text-button" onClick={()=>{setMode('reset');setError('');setMessage('');}}>Forgot password?</button></> : <button type="button" className="text-button" onClick={()=>{setMode('login');setError('');setMessage('');}}>Back to sign in</button>}</div>
    </form></div>;
}

function AccountManagement() {
  const [rows,setRows]=useState([]), [search,setSearch]=useState(''), [error,setError]=useState(''), [busy,setBusy]=useState(false);
  const load=async()=>{setBusy(true);setError('');try{const result=await api(`/admin/accounts/?search=${encodeURIComponent(search)}`);setRows(Array.isArray(result)?result:result.results||[]);}catch(e){setError(e.message);}finally{setBusy(false);}};
  useEffect(()=>{load();},[search]);
  const update=async(row,changes)=>{if(!window.confirm(`Apply this account access change for ${row.name}?`))return;try{await api(`/admin/accounts/${row.id}/`,{method:'PATCH',body:JSON.stringify(changes)});await load();}catch(e){setError(e.message);}};
  return <div className="panel list-panel"><div className="list-toolbar"><div className="list-search"><Search size={16}/><input aria-label="Search accounts" placeholder="Search accounts…" value={search} onChange={e=>setSearch(e.target.value)}/></div><span className="record-count">Administrator access only</span></div>{error&&<div className="notice warning">{error}<button className="text-button" onClick={load}>Retry</button></div>}<div className="table-wrap"><table><thead><tr><th>Name</th><th>Username</th><th>Email</th><th>Role</th><th>Designation</th><th>Status</th><th>Welfare access</th><th>Actions</th></tr></thead><tbody>{rows.map(row=><tr key={row.id}><td>{row.name}</td><td>{row.username}</td><td>{row.email||'—'}</td><td><select aria-label={`Role for ${row.username}`} value={row.role} onChange={e=>update(row,{role:e.target.value})}><option value="member">Member</option><option value="staff">Staff</option><option value="administrator">Administrator</option></select></td><td>{row.designation||'—'} <button className="text-button" onClick={()=>{const value=window.prompt('Set the staff designation (leave blank to clear).',row.designation||'');if(value!==null)update(row,{designation:value});}}>Edit</button></td><td>{row.is_active?'Active':'Inactive'}</td><td>{row.can_access_welfare?'Authorized':'No access'}</td><td><button className="secondary-button" onClick={()=>update(row,{can_access_welfare:!row.can_access_welfare})}>{row.can_access_welfare?'Revoke welfare':'Grant welfare'}</button> <button className="secondary-button" onClick={()=>update(row,{is_active:!row.is_active})}>{row.is_active?'Deactivate':'Activate'}</button></td></tr>)}</tbody></table>{!busy&&!rows.length&&<div className="table-empty">No accounts found.</div>}{busy&&<div className="table-empty">Loading accounts…</div>}</div></div>;
}

function Dashboard({ data, loading, onOpen, role }) {
  const players = data.players || [], matches = data.matches || [], training = data.training || [], announcements = data.announcements || [];
  const summary = data.dashboard || {};
  const statRows=[['ACTIVE PLAYERS',summary.active_players ?? players.filter(p=>p.status==='active').length,'Registered squad','red'],['MATCHES PLAYED',summary.matches_played ?? matches.filter(m=>m.status==='completed').length,'Completed with scores','blue'],['TRAINING SESSIONS',summary.training_sessions ?? training.length,'Recorded sessions','green'],['WIN RATE',summary.win_rate == null ? '—' : `${summary.win_rate}%`,summary.win_rate == null ? 'No scored matches yet' : 'Scored completed matches','amber']];
  if(role==='administrator'){statRows.push(['ACTIVE ACCOUNTS',summary.active_accounts??0,'All account roles','blue'],['INACTIVE ACCOUNTS',summary.inactive_accounts??0,'Access currently disabled','amber']);}
  const nextMatch = summary.next_match || [...matches].filter(m => m.status === 'scheduled').sort((a,b) => (a.date || '').localeCompare(b.date || ''))[0], nextTraining = summary.next_training || training[0];
  return <>
    <div className="stats-grid">{statRows.map(([label,value,note,tint])=><Stat key={label} icon={label.includes('MATCH')?Trophy:label.includes('TRAINING')?Activity:label.includes('RATE')?ChartNoAxesCombined:Users} label={label} value={value} note={note} tint={tint}/>)}</div>
    <div className="dashboard-grid"><div className="panel upcoming-panel"><div className="panel-head"><div><h2>Coming up</h2><p>Your next team commitments</p></div><button className="text-button" onClick={() => onOpen('Matches')}>View calendar <span>→</span></button></div><div className="upcoming-cards"><div className="event-card match-card"><div className="event-label"><span className="event-icon red-bg"><Trophy size={16}/></span><span>NEXT MATCH</span><span className="event-tag">FIXTURE</span></div>{nextMatch ? <><h3>Wazimba <span>vs</span> {nextMatch.opponent}</h3><div className="event-details"><span><CalendarDays size={14}/>{prettyDate(nextMatch.date)}</span><span><Activity size={14}/>{nextMatch.venue || 'Venue TBD'}</span></div><div className="event-bottom"><span>{nextMatch.competition_name || 'Competition TBC'}</span><button onClick={() => onOpen('Matches')}>Match details <span>→</span></button></div></> : <EmptySmall text="No upcoming match yet"/>}</div><div className="event-card training-card"><div className="event-label"><span className="event-icon green-bg"><Dumbbell size={16}/></span><span>NEXT TRAINING</span></div>{nextTraining ? <><h3>{nextTraining.title}</h3><div className="event-details"><span><CalendarDays size={14}/>{prettyDate(nextTraining.date)}</span><span><Activity size={14}/>{nextTraining.start_time || 'Time TBC'} · {nextTraining.location || 'Location TBC'}</span></div><div className="event-bottom"><span>All squad</span><button onClick={() => onOpen('Training')}>View session <span>→</span></button></div></> : <EmptySmall text="No training scheduled"/>}</div></div></div>
      <div className="panel form-panel"><div className="panel-head"><div><h2>Squad snapshot</h2><p>Current registered players</p></div><button className="text-button" onClick={() => onOpen('Players')}>All players <span>→</span></button></div><div className="squad-list">{players.slice(0,4).map((p,i)=><div className="squad-row" key={p.id}><div className={`player-avatar av-${i%4}`}>{p.full_name?.split(' ').map(n=>n[0]).slice(0,2).join('')}</div><div className="squad-name"><b>{p.full_name}</b><span>{p.position || 'Position not set'}</span></div><span className="jersey">#{p.jersey_number ?? '—'}</span><span className={`status-pill ${p.status === 'active' ? 'active' : 'muted'}`}>{p.status || 'active'}</span></div>)}</div>{players.length === 0 && <EmptySmall text="Add your squad to get started"/>}</div>
    </div>
    <div className="lower-grid"><div className="panel"><div className="panel-head"><div><h2>Season form</h2><p>Match results recorded this season</p></div><button className="text-button" onClick={() => onOpen('Performance')}>Analyze <span>→</span></button></div><div className="form-empty">{loading ? 'Loading team records…' : (summary.matches_played || 0) > 0 ? `${summary.wins || 0} wins · ${summary.losses || 0} losses · ${summary.draws || 0} draws from ${summary.matches_played} scored matches.` : 'No completed matches with scores yet. Record a match result to see team form.'}</div></div><div className="panel"><div className="panel-head"><div><h2>Latest update</h2><p>Team communications</p></div><button className="text-button" onClick={() => onOpen('Announcements')}>All updates <span>→</span></button></div>{(summary.recent_news||[]).slice(0,1).map(story=><div className="announcement-row" key={`news-${story.id}`}><div className="announcement-icon"><Newspaper size={16}/></div><div><b>{story.title}</b><span>{story.source_name||'Wazimba news'} · {prettyDate(story.published_at)}</span></div></div>)}{announcements.length ? announcements.slice(0,1).map(a=><div className="announcement-row" key={a.id}><div className="announcement-icon"><Newspaper size={16}/></div><div><b>{a.title}</b><span>{a.category || 'Announcement'} · {prettyDate(a.published_at || a.created_at)}</span></div></div>) : <EmptySmall text="No announcements yet"/>}</div></div>
    {role==='administrator'&&<section className="panel admin-activity"><div className="panel-head"><div><h2>Account overview</h2><p>Live totals from Wazimba user accounts</p></div><a href={import.meta.env.VITE_ADMIN_URL||'http://127.0.0.1:8000/admin/'} target="_blank" rel="noreferrer">Django admin ↗</a></div><div className="account-role-summary">{(summary.accounts||[]).map(item=><div key={item.role}><span>{item.role}</span><b>{item.total}</b><small>{item.active} active</small></div>)}</div><div className="panel-head"><div><h2>Recent account activity</h2><p>Role and access changes recorded by the server</p></div></div>{(summary.recent_admin_activity||[]).map(item=><div className="activity-row" key={item.id}><b>{item.actor_name}</b><span>updated {item.target_name}</span><small>{Object.entries(item.changes||{}).map(([key,value])=>`${key}: ${String(value.from)} → ${String(value.to)}`).join(' · ')}</small></div>)}{!summary.recent_admin_activity?.length&&<EmptySmall text="No account changes recorded yet."/>}</section>}
    <div className="quick-links"><span>QUICK ACCESS</span>{[['Training schedule', 'Training', CalendarDays], ['Team performance', 'Performance', ChartNoAxesCombined], ['Learning centre', 'Tactical learning', BookOpen], ['Team archive', 'Historical archive', Archive]].map(([label,page,Icon])=><button key={page} onClick={()=>onOpen(page)}><Icon size={16}/>{label}<span>↗</span></button>)}</div>
  </>;
}

function Stat({ icon: Icon, label, value, note, tint }) { return <div className="stat-card"><div className={`stat-icon ${tint}`}><Icon size={18}/></div><div className="stat-label">{label}</div><div className="stat-value">{value}</div><div className="stat-note">{note}</div></div>; }
function EmptySmall({ text }) { return <div className="empty-small">{text}</div>; }
function SectionPage({ page, data, query, onQuery, loading, isStaff, canAccessWelfare, onOpen, onCreate, onEdit, onChanged }) {
  const config = {
    Players: ['players', [['Player','full_name'],['Position','position'],['Jersey','jersey_number'],['Status','status']]],
    Matches: ['matches', [['Opponent','opponent'],['Competition','competition_name'],['Date','date'],['Score','score'],['Venue','venue'],['Status','status']]],
    Training: ['training', [['Session','title'],['Date','date'],['Time','start_time'],['Location','location'],['Session type','session_type']]],
    Tournaments: ['tournaments', [['Tournament','name'],['Location','location'],['Start date','start_date'],['Status','status']]],
    Announcements: ['announcements', [['Announcement','title'],['Category','category'],['Published','published_at'],['Source','source_url']]],
    Seasons: ['seasons', [['Season','name'],['Start date','start_date'],['End date','end_date'],['Status','status']]],
    'Team events': ['events', [['Event','title'],['Category','category'],['Date','date'],['Location','location']]],
    'Media gallery': ['media', [['Title','title'],['Category','category'],['Media','media_url'],['Consent','consent_confirmed']]],
    'Alumni & supporters': ['alumni', [['Name','full_name'],['Position','former_position'],['Seasons','seasons_played'],['Mentorship','mentorship_available']]],
    'Injury & welfare': ['injuries', [['Player','player_name'],['Injury date','injury_date'],['Status','status'],['Description','description']]],
    'Rules & laws': ['learning', [['Title','title'],['Category','category'],['Official','is_official'],['Source','source_url']]],
    'Tactical learning': ['learning', [['Title','title'],['Category','category'],['Official','is_official'],['Source','source_url']]],
    'Video resources': ['learning', [['Title','title'],['Category','category'],['Official','is_official'],['Source','source_url']]],
    'News & information': ['news', [['Story','title'],['Category','category'],['Published','published_at'],['Source','source_name']]],
  };
  const [filter, setFilter] = useState('all');
  const item = config[page];
  const key = item?.[0];
  const category = ({'Rules & laws':'law','Tactical learning':'tactics','Video resources':'video'})[page];
  const rows = key ? data[key] || [] : [];
  const filtered = useMemo(() => rows.filter(row => JSON.stringify(row).toLowerCase().includes(query.toLowerCase()) && (!category || row.category === category) && (filter === 'all' || row.status === filter || String(row.is_official) === filter || String(row.consent_confirmed) === filter)), [rows, query, filter, category]);
  if (page === 'Historical archive') return <ArchiveSection data={data} onOpen={onOpen}/>;
  if (page === 'News & information') return <NewsCenter rows={filtered} announcements={data.announcements||[]} onEdit={onEdit} onChanged={onChanged} isStaff={isStaff}/>;
  if (page === 'Video resources') return <VideoLibrary rows={filtered}/>;
  if (page === 'Injury & welfare' && !canAccessWelfare) return <div className="notice"><Shield size={16}/>Injury and welfare records are restricted to authorized team staff.</div>;
  if (!item) return <div className="panel table-empty">This section is unavailable.</div>;
  const cols = item[1];
  const source = ({players:'players',matches:'matches',training:'training-sessions',tournaments:'tournaments',announcements:'announcements',seasons:'seasons',events:'team-events',media:'media',alumni:'alumni',injuries:'injury-records',learning:'learning-resources'})[key];
  const remove = async row => { if (!window.confirm(`Delete “${row.full_name || row.title || row.opponent || row.name}”?`)) return; try { await api(`/${source}/${row.id}/`,{method:'DELETE'}); onChanged(); } catch (e) { window.alert(e.message); } };
  return <div className="panel list-panel"><div className="list-toolbar"><div className="list-search"><Search size={16}/><input placeholder={`Search ${page.toLowerCase()}…`} value={query} onChange={e=>onQuery(e.target.value)}/></div><select className="filter-select" aria-label="Filter records" value={filter} onChange={e=>setFilter(e.target.value)}><option value="all">All records</option>{['active','upcoming','ongoing','scheduled','completed','cancelled','injured','suspended','inactive','assessed','recovering','return_training','return_play'].map(value=><option key={value} value={value}>{value.replaceAll('_',' ')}</option>)}<option value="true">Confirmed / official</option><option value="false">Unconfirmed / unofficial</option></select><span className="record-count">{loading ? 'Loading…' : `${filtered.length} records`}</span></div><div className="table-wrap"><table><thead><tr>{cols.map(([label])=><th key={label}>{label}</th>)}{isStaff&&<th>Actions</th>}</tr></thead><tbody>{filtered.map((row,i)=><tr key={row.id || i}>{cols.map(([label,field])=><td key={field}>{field === 'status' ? <span className={`status-pill ${['active','scheduled','upcoming','ongoing','return_play'].includes(row[field]) ? 'active' : 'muted'}`}>{row[field] || '—'}</span> : field.includes('date') || field === 'published_at' ? prettyDate(row[field]) : field === 'score' ? `${row.wazimba_score ?? '—'} – ${row.opponent_score ?? '—'}` : field === 'source_url' || field === 'media_url' ? row[field] ? <a href={row[field]} target="_blank" rel="noreferrer">Open ↗</a> : '—' : typeof row[field] === 'boolean' ? row[field] ? 'Yes' : 'No' : row[field] ?? '—'}</td>)}{isStaff&&<td className="actions-cell"><button className="secondary-button" onClick={()=>onEdit(page,row)}>Edit</button><button className="danger-button" onClick={()=>remove(row)}>Delete</button>{page==='Matches'&&<button className="secondary-button" onClick={()=>onCreate('Match stats',{match:row.id})}>Record stats</button>}{page==='Training'&&<button className="secondary-button" onClick={()=>onCreate('Training attendance',{session:row.id})}>Attendance</button>}{page==='Seasons'&&<button className="secondary-button" onClick={()=>onCreate('Season registration',{season:row.id})}>Register player</button>}{page==='Team events'&&<button className="secondary-button" onClick={()=>onCreate('Team event attendance',{event:row.id})}>Attendance</button>}</td>}</tr>)}</tbody></table>{filtered.length === 0 && <div className="table-empty">{loading ? 'Loading records…' : `No ${page.toLowerCase()} records match this view.`}</div>}</div><div className="table-foot">Showing <b>{filtered.length}</b> {page.toLowerCase()}{!isStaff&&page==='Injury & welfare'?' (staff access required)':''}</div></div>;
}

function NewsCenter({rows,announcements=[],onEdit,onChanged,isStaff}) {
  const [category,setCategory]=useState('all'); const [search,setSearch]=useState(''); const [featuredIndex,setFeaturedIndex]=useState(0); const [paused,setPaused]=useState(false); const [selected,setSelected]=useState(null);
  const stories=rows.filter(x=>x.is_published!==false); const visibleStories=isStaff?rows:stories; const featured=stories.filter(x=>x.is_featured); const active=featured.length?featured[featuredIndex%featured.length]:null;
  const filtered=visibleStories.filter(x=>(category==='all'||x.category===category)&&JSON.stringify(x).toLowerCase().includes(search.toLowerCase()));
  const categories=[['all','All rugby news'],['kenyan','Kenyan Rugby'],['international','International Rugby'],['wazimba','Wazimba News']];
  const step=direction=>setFeaturedIndex(i=>(i+direction+featured.length)%Math.max(1,featured.length));
  const reduced=window.matchMedia?.('(prefers-reduced-motion: reduce)').matches;
  useEffect(()=>{if(reduced||paused||featured.length<2)return;const timer=setInterval(()=>step(1),6500);return()=>clearInterval(timer);},[reduced,paused,featured.length]);
  if(selected){const story=visibleStories.find(x=>x.id===selected);if(!story)return <div className="panel table-empty"><p>This story is no longer available.</p><button className="text-button" onClick={()=>setSelected(null)}>Back to news</button></div>;return <article className="panel article-detail"><button className="text-button" onClick={()=>setSelected(null)}>← All news</button>{story.image_file&&<img className="article-hero" src={story.image_file} alt=""/>}<span className="eyebrow">{story.is_published===false?'DRAFT · ':''}{categories.find(x=>x[0]===story.category)?.[1]||story.category} · {prettyDate(story.published_at)}</span><h2>{story.title}</h2>{story.summary&&<p className="article-summary">{story.summary}</p>}{story.kind==='original'?<div className="article-body">{story.body}</div>:<div className="news-actions"><span>{story.source_name||'External publisher'}</span>{story.source_url&&<a className="primary-button" href={story.source_url} target="_blank" rel="noreferrer">Read publisher story ↗</a>}</div>}</article>;}
  return <div className="news-center" onKeyDown={e=>{if(e.key==='ArrowLeft')step(-1);if(e.key==='ArrowRight')step(1);}}>
    <section className="panel news-feature" aria-label="Featured rugby stories" tabIndex="0" onMouseEnter={()=>setPaused(true)} onMouseLeave={()=>setPaused(false)} onFocus={()=>setPaused(true)} onBlur={e=>{if(!e.currentTarget.contains(e.relatedTarget))setPaused(false);}}>
      {active?<><div className="news-feature-copy"><span className="eyebrow">FEATURED · {categories.find(x=>x[0]===active.category)?.[1]||active.category} · {active.source_name||'Wazimba'}</span><h2><button className="feature-title" onClick={()=>setSelected(active.id)}>{active.title}</button></h2><p>{active.summary||active.body?.slice(0,240)||'Open the story for more information.'}</p><div className="news-actions"><button className="primary-button" onClick={()=>setSelected(active.id)}>Read story →</button>{featured.length>1&&<><button className="secondary-button" aria-label="Previous featured story" onClick={()=>step(-1)}>‹</button><button className="secondary-button" aria-label="Next featured story" onClick={()=>step(1)}>›</button><button className="secondary-button" aria-label={paused?'Resume carousel':'Pause carousel'} onClick={()=>setPaused(x=>!x)}>{paused?'Play':'Pause'}</button></>}</div><div className="carousel-indicators">{featured.map((story,index)=><button key={story.id} aria-label={`Show featured story ${index+1}`} aria-current={index===featuredIndex?'true':undefined} onClick={()=>setFeaturedIndex(index)}/>)}</div></div>{active.image_file?<img className="news-feature-image" src={active.image_file} alt="" onError={e=>{e.currentTarget.style.display='none';}}/>:<div className="news-feature-art" aria-hidden="true"><Newspaper size={56}/><span>WAZIMBA RUGBY 7s</span></div>}</>:<div className="news-feature-empty"><span className="eyebrow">WAZIMBA RUGBY 7s · NEWS</span><h2>No featured stories yet</h2><p>Published stories selected by staff will appear here.</p></div>}
    </section>
    <div className="news-search list-search"><Search size={16}/><input aria-label="Search rugby news" placeholder="Search rugby stories…" value={search} onChange={e=>setSearch(e.target.value)}/></div><div className="tabs news-tabs" role="tablist">{categories.map(([value,label])=><button key={value} role="tab" aria-selected={category===value} className={`tab-button ${category===value?'active':''}`} onClick={()=>setCategory(value)}>{label}</button>)}</div>
    <div className="news-list">{filtered.map(row=><article className="panel news-card" key={row.id}>{row.image_file&&<img className="news-thumb" src={row.image_file} alt={row.title} onError={e=>{e.currentTarget.style.display='none';}}/>}<div><span className="eyebrow">{row.is_published===false?'DRAFT · ':''}{categories.find(x=>x[0]===row.category)?.[1]||row.category} · {row.source_name||'Wazimba'} · {prettyDate(row.published_at)}</span><h3><button className="story-title" onClick={()=>setSelected(row.id)}>{row.title}</button></h3><p>{row.summary||row.body?.slice(0,220)}</p></div><div className="news-actions"><button className="secondary-button" onClick={()=>setSelected(row.id)}>Read story</button>{isStaff&&<><button className="secondary-button" onClick={()=>onEdit('News & information',row)}>Edit</button><button className="danger-button" onClick={async()=>{if(!window.confirm(`Delete story “${row.title}”?`))return;try{await api(`/news/${row.id}/`,{method:'DELETE'});onChanged();}catch(e){window.alert(e.message);}}}>Delete</button></>}</div></article>)}{!filtered.length&&<div className="panel table-empty">No published stories in this category yet.</div>}</div>
    <section className="panel latest-announcements"><h2>Wazimba announcements</h2>{announcements.filter(a=>a.is_published!==false).slice(0,4).map(a=><article key={a.id}><b>{a.title}</b><span>{a.category} · {prettyDate(a.published_at)}</span><p>{a.body}</p></article>)}{!announcements.some(a=>a.is_published!==false)&&<p>No team announcements have been published yet.</p>}</section>
  </div>;
}
function VideoLibrary({rows}) {
  return <div className="video-library">{rows.map(row=><article className="panel video-card" key={row.id}><span className="eyebrow">{row.is_published===false?'DRAFT · ':''}{row.topic||row.category}</span><h3>{row.title}</h3><p>{row.summary||'No description provided.'}</p>{row.uploaded_file?<video controls preload="metadata" src={row.uploaded_file} />:row.embed_url?<iframe title={row.title} src={videoEmbedUrl(row.embed_url)} allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture" allowFullScreen/>:row.source_url?<a href={row.source_url} target="_blank" rel="noreferrer">Open video ↗</a>:<p>Video URL not available.</p>}</article>)}{!rows.length&&<div className="panel table-empty">No video resources yet. Authorized staff can upload a team video or add a YouTube/Vimeo link.</div>}</div>;
}
function videoEmbedUrl(value) { try { const u=new URL(value); if(u.hostname==='youtu.be')return `https://www.youtube-nocookie.com/embed/${u.pathname.slice(1)}`; if(u.hostname.includes('youtube.com'))return `https://www.youtube-nocookie.com/embed/${u.searchParams.get('v')||u.pathname.split('/').filter(Boolean).pop()}`; if(u.hostname.includes('vimeo.com'))return `https://player.vimeo.com/video/${u.pathname.split('/').filter(Boolean).pop()}`; } catch {} return value; }

function PerformanceSection({ seasons, initialTab='team' }) {
  const [tab,setTab]=useState(initialTab), [season,setSeason]=useState(''), [result,setResult]=useState(null), [busy,setBusy]=useState(true), [error,setError]=useState('');
  useEffect(()=>setTab(initialTab),[initialTab]);
  useEffect(()=>{let alive=true;setBusy(true);setError('');const params=season?`?season=${encodeURIComponent(season)}`:'';const endpoint=tab==='players'?`/performance/players/${params}`:tab==='reports'?`/reports/${params}`:`/performance/team/${params}`;api(endpoint).then(value=>{if(alive)setResult(value);}).catch(e=>{if(alive)setError(e.message);}).finally(()=>{if(alive)setBusy(false);});return()=>{alive=false;};},[tab,season]);
  const changeTab=value=>{setTab(value);};
  return <div className="performance-wrap"><div className="panel performance-toolbar"><div className="tabs" role="tablist">{[['team','Team analytics'],['players','Player performance'],['reports','Reports']].map(([id,label])=><button role="tab" aria-selected={tab===id} className={`tab-button ${tab===id?'active':''}`} key={id} onClick={()=>changeTab(id)}>{label}</button>)}</div><select className="filter-select" value={season} onChange={e=>setSeason(e.target.value)} aria-label="Season"><option value="">All seasons</option>{seasons.map(s=><option key={s.id} value={s.id}>{s.name}</option>)}</select></div>
    {error&&<div className="notice warning"><Shield size={16}/>{error}</div>}{busy?<div className="panel empty-panel">Loading performance records…</div>:tab==='team'?<TeamAnalytics data={result||{}}/>:tab==='players'?<PlayerAnalytics rows={Array.isArray(result)?result:[]}/>:<ReportsPanel data={result||{}} season={season}/>}
  </div>;
}

function TeamAnalytics({data}) {
  const stats=[['Matches played',data.matches_played||0],['Wins',data.wins||0],['Losses',data.losses||0],['Draws',data.draws||0],['Win rate',data.win_rate==null?'—':`${data.win_rate}%`],['Points for',data.points_for||0],['Points against',data.points_against||0],['Training attendance',data.training_attendance_rate==null?'—':`${data.training_attendance_rate}%`]];
  return <><div className="performance-stats">{stats.map(([label,value])=><div className="performance-stat" key={label}><span>{label}</span><b>{value}</b></div>)}</div><div className="panel list-panel"><div className="panel-head"><div><h2>Scored match results</h2><p>Computed from completed match records with both scores present.</p></div></div><div className="table-wrap"><table><thead><tr><th>Date</th><th>Opponent</th><th>Score</th><th>Result</th></tr></thead><tbody>{(data.match_results||[]).map(m=><tr key={m.id}><td>{prettyDate(m.date)}</td><td>{m.opponent}</td><td>{m.score_for} – {m.score_against}</td><td><span className={`status-pill ${m.result==='Win'?'active':'muted'}`}>{m.result}</span></td></tr>)}</tbody></table>{!data.matches_played&&<div className="table-empty">No completed matches with recorded scores. Add or update a match result to populate analytics.</div>}</div><div className="table-foot">Training records: {data.training_sessions||0} sessions · Attendance entries: {data.training_attendance_total||0}</div></div></>;
}

function PlayerAnalytics({rows}) { return <div className="panel list-panel"><div className="panel-head"><div><h2>Player match contributions</h2><p>Aggregated only from recorded match participation rows.</p></div></div><div className="table-wrap"><table><thead><tr>{['Player','Position','Apps','Starts','Minutes','Tries','Assists','Tackles','Turnovers','Errors'].map(c=><th key={c}>{c}</th>)}</tr></thead><tbody>{rows.map(p=><tr key={p.player_id}><td>{p.player__full_name}</td><td>{p.player__position||'—'}</td><td>{p.appearances}</td><td>{p.starts}</td><td>{p.minutes||0}</td><td>{p.tries||0}</td><td>{p.assists||0}</td><td>{p.tackles||0}</td><td>{p.turnovers_won||0}</td><td>{p.errors||0}</td></tr>)}</tbody></table>{rows.length===0&&<div className="table-empty">No player match statistics recorded. Use “Record stats” on a match to add participation data.</div>}</div></div>; }

function ReportsPanel({data,season}) { const [busy,setBusy]=useState(false),[error,setError]=useState('');const save=async()=>{setBusy(true);setError('');try{await download(`/reports/csv/${season?`?season=${encodeURIComponent(season)}`:''}`,'wazimba-season-report.csv');}catch(e){setError(e.message);}finally{setBusy(false);}};const team=data.team||{};return <div className="report-grid"><div className="panel report-summary"><div className="panel-head"><div><h2>{data.season?.name||'All seasons'} report</h2><p>Live summary generated from saved team records.</p></div><button className="primary-button" onClick={save} disabled={busy}><FileText size={16}/>{busy?'Preparing…':'Export CSV'}</button></div>{error&&<div className="form-error">{error}</div>}<div className="performance-stats compact">{[['Matches',team.matches_played||0],['Wins',team.wins||0],['Points scored',team.points_for||0],['Training sessions',data.training_sessions||0]].map(([label,value])=><div className="performance-stat" key={label}><span>{label}</span><b>{value}</b></div>)}</div><p className="report-note">The export includes scored match results and per-player match contributions. Values are calculated from recorded records; missing data is not estimated.</p></div><div className="panel report-summary"><h2>Report contents</h2><ul className="report-list"><li>Team results and win rate</li><li>Scored match-by-match summary</li><li>Player appearances, minutes and match statistics</li><li>Training session total</li></ul></div></div>; }

function ReviewSection({matches,reviews,isStaff,onChanged,onCreate,onEdit}) { const [query,setQuery]=useState('');const entries=matches.filter(m=>m.status==='completed'||reviews.some(r=>r.match===m.id)).filter(m=>JSON.stringify(m).toLowerCase().includes(query.toLowerCase()));return <div className="panel list-panel"><div className="list-toolbar"><div className="list-search"><Search size={16}/><input placeholder="Search matches…" value={query} onChange={e=>setQuery(e.target.value)}/></div><span className="record-count">{entries.length} match reviews</span></div><div className="review-list">{entries.map(match=>{const review=reviews.find(r=>r.match===match.id);return <article className="review-card" key={match.id}><div className="review-card-head"><div><h3>Wazimba vs {match.opponent}</h3><span>{prettyDate(match.date)} · {match.wazimba_score??'—'} – {match.opponent_score??'—'} · {match.competition_name||'Match'}</span></div>{isStaff&&<button className="secondary-button" onClick={()=>review?onEdit(review):onCreate(match.id)}>{review?'Edit review':'Add review'}</button>}</div>{review?<div className="review-content">{[['Went well',review.went_well],['Needs work',review.needs_work],['Tactical observations',review.tactical_observations],['Lessons learned',review.lessons_learned],['Training objectives',review.training_objectives]].filter(([,v])=>v).map(([label,value])=><div key={label}><b>{label}</b><p>{value}</p></div>)}</div>:<p className="empty-inline">No review recorded for this match yet.</p>}</article>;})}{!entries.length&&<div className="table-empty">No completed matches found to review. Record a match result first.</div>}</div>{!isStaff&&<div className="table-foot">Match reviews are visible to team members. Staff permissions are required to create or edit them.</div>}</div>; }

function ArchiveSection({data,onOpen}) { const cards=[['Seasons',data.seasons||[],'Seasons'],['Matches',data.matches||[],'Matches'],['Players',data.players||[],'Players'],['Tournaments',data.tournaments||[],'Tournaments'],['Media items',data.media||[],'Media gallery'],['Team events',data.events||[],'Team events']];return <div className="archive-wrap"><div className="archive-cards">{cards.map(([label,rows,page])=><button className="archive-card" key={label} onClick={()=>onOpen(page)}><span>{label}</span><b>{rows.length}</b><small>Browse records →</small></button>)}</div><div className="notice"><Archive size={16}/>The archive is built from the seasons, results, players, media and events already recorded in the system.</div></div>; }

function CreateModal({ page, seasons=[], tournaments=[], matches=[], training=[], events=[], players=[], record, onClose, onSaved }) {
  const [busy,setBusy]=useState(false), [error,setError]=useState('');
  const select=(choices)=>['select',choices];
  const seasonChoices=[['','No season'],...seasons.map(x=>[String(x.id),x.name])];
  const matchChoices=[['','Select match'],...matches.map(x=>[String(x.id),`${x.date} · ${x.opponent}`])];
  const playerChoices=[['','Select player'],...players.map(x=>[String(x.id),x.full_name])];
  const trainingChoices=[['','Select session'],...training.map(x=>[String(x.id),`${x.date} · ${x.title}`])];
  const eventChoices=[['','Select event'],...events.map(x=>[String(x.id),`${x.date} · ${x.title}`])];
  const fields={
    Players:[['full_name','Full name','text',true],['email','Email','email'],['position','Position',...select(['Centre','Wing','Fly-half','Scrum-half','Forward','Full Back'])],['jersey_number','Jersey number','number'],['status','Status',...select(['active','injured','suspended','inactive'])],['joined_at','Joined','date']],
    Matches:[['opponent','Opponent','text',true],['date','Date','date',true],['venue','Venue','text'],['competition_name','Competition','text'],['season','Season',...select(seasonChoices)],['tournament','Tournament',...select([['','No tournament'],...tournaments.map(x=>[String(x.id),x.name])])],['status','Status',...select(['scheduled','completed','cancelled'])],['wazimba_score','Wazimba score','number'],['opponent_score','Opponent score','number'],['notes','Match notes','textarea']],
    Training:[['title','Session name','text',true],['date','Date','date',true],['start_time','Start time','time'],['location','Location','text'],['session_type','Session type',...select(['Team session','Conditioning','Gym','Ball skills','Defence','Attack','Set plays'])],['objectives','Objectives','textarea'],['drills','Drills','textarea'],['season','Season',...select(seasonChoices)]],
    Tournaments:[['name','Tournament name','text',true],['location','Location','text'],['organizer','Organizer','text'],['start_date','Start date','date'],['end_date','End date','date'],['status','Status',...select(['upcoming','ongoing','completed'])],['official_url','Official URL','url'],['season','Season',...select(seasonChoices)]],
    'News article':[['title','Headline','text',true],['kind','Story type',...select([['original','Original Wazimba article'],['external','Curated external story']])],['category','Category',...select([['kenyan','Kenyan Rugby'],['international','International Rugby'],['wazimba','Wazimba News']])],['summary','Summary','text'],['body','Article text','textarea'],['source_name','Publisher or author','text'],['source_url','Publisher URL','url'],['image_file','Story image (JPG, PNG, WebP)','file'],['is_published','Published','checkbox'],['is_featured','Featured','checkbox']],
    Announcements:[['title','Title','text',true],['category','Category',...select(['General','Training','Match','Tournament','Administrative','Kenyan Rugby','International Rugby'])],['body','Announcement','textarea',true],['source_url','Source URL','url'],['is_published','Published','checkbox'],['is_featured','Feature in news carousel','checkbox']],
    Seasons:[['name','Season name','text',true],['start_date','Start date','date',true],['end_date','End date','date'],['status','Status',...select(['active','completed','upcoming'])]],
    'Team events':[['title','Event name','text',true],['category','Category',...select(['meeting','bonding','welfare','fundraising','other'])],['date','Date','date',true],['start_time','Start time','time'],['location','Location','text'],['description','Description','textarea'],['season','Season',...select(seasonChoices)]],
    'Rules & laws':[['title','Title','text',true],['category','Category','hidden','law'],['summary','Explanation','textarea'],['source_url','Official source URL','url'],['is_official','Official source','checkbox'],['published_at','Published or updated','date']],
    'Tactical learning':[['title','Title','text',true],['category','Category','hidden','tactics'],['summary','Learning content','textarea'],['source_url','Resource URL','url'],['is_official','Official source','checkbox']],
    'Video resources':[['title','Title','text',true],['category','Category','hidden','video'],['topic','Rugby topic or skill','text'],['summary','Description or learning objectives','textarea'],['source_url','External video URL','url'],['embed_url','YouTube or Vimeo URL','url'],['uploaded_file','Upload video (MP4, WebM, Ogg)','file'],['season','Season',...select(seasonChoices)],['match','Match',...select(matchChoices)],['training_session','Training session',...select(trainingChoices)],['event','Team event',...select(eventChoices)],['is_published','Published','checkbox'],['is_official','Official resource','checkbox']],
    'Media gallery':[['title','Title','text',true],['category','Category',...select(['match','training','tournament','event','team'])],['media_url','Image or video URL','url',true],['consent_confirmed','Consent confirmed','checkbox'],['season','Season',...select(seasonChoices)],['match','Match',...select(matchChoices)]],
    'Alumni & supporters':[['full_name','Full name','text',true],['former_position','Former position','text'],['seasons_played','Seasons played','text'],['bio','Biography','textarea'],['contact_email','Contact email','email'],['contact_consent','Contact consent','checkbox'],['mentorship_available','Available to mentor','checkbox']],
    'Injury & welfare':[['player','Player',...select(playerChoices),true],['injury_date','Injury date','date',true],['description','Description','textarea',true],['status','Recovery status',...select(['assessed','recovering','return_training','return_play'])],['staff_notes','Restricted staff notes','textarea']],
    'Match stats':[['match','Match',...select(matchChoices),true],['player','Player',...select(playerChoices),true],['started','Started','checkbox'],['minutes_played','Minutes played','number'],['tries','Tries','number'],['assists','Assists','number'],['tackles','Tackles','number'],['turnovers_won','Turnovers won','number'],['errors','Errors','number']],
    'Training attendance':[['session','Training session',...select(trainingChoices),true],['player','Player',...select(playerChoices),true],['attended','Attended','checkbox'],['notes','Attendance notes','text']],
    'Team event attendance':[['event','Team event',...select(eventChoices),true],['player','Player',...select(playerChoices),true],['attended','Attended','checkbox'],['notes','Attendance notes','text']],
    'Season registration':[['season','Season',...select(seasonChoices),true],['player','Player',...select(playerChoices),true]],
    'Match review':[['match','Match',...select(matchChoices),true],['went_well','What went well','textarea'],['needs_work','What needs work','textarea'],['tactical_observations','Tactical observations','textarea'],['lessons_learned','Lessons learned','textarea'],['training_objectives','Training objectives','textarea']],
  }[page] || [];
  const endpoints={'Players':'players','Matches':'matches','Training':'training-sessions','Tournaments':'tournaments','Announcements':'announcements','News article':'news','Seasons':'seasons','Team events':'team-events','Rules & laws':'learning-resources','Tactical learning':'learning-resources','Video resources':'learning-resources','Media gallery':'media','Alumni & supporters':'alumni','Injury & welfare':'injury-records','Match stats':'match-participations','Training attendance':'training-attendance','Team event attendance':'team-event-attendance','Season registration':'season-registrations','Match review':'match-reviews'};
  const title=record?.id?'Edit':page==='Match stats'?'Record match statistics':page==='Training attendance'?'Record training attendance':page==='Team event attendance'?'Record event attendance':page==='Season registration'?'Register player to season':page==='Match review'?'Match review':`Add ${({'Players':'player','Matches':'match','Training':'training session','Tournaments':'tournament','Announcements':'announcement','News article':'news story','Seasons':'season','Team events':'team event','Media gallery':'media item','Alumni & supporters':'alumni profile','Injury & welfare':'welfare record'})[page]||'resource'}`;
  const submit=async e=>{e.preventDefault();setBusy(true);setError('');const form=e.currentTarget;const values={};for(const [name,label,type,extra] of fields){const el=form.elements.namedItem(name);if(type==='checkbox')values[name]=el.checked;else if(type==='file'){if(el.files?.[0])values[name]=el.files[0];}else if(type==='hidden')values[name]=extra;else if(type==='number')values[name]=el.value===''?null:Number(el.value);else if(['season','tournament','match','player','session','event'].includes(name))values[name]=el.value===''?null:Number(el.value);else values[name]=el.value;}
    try{const editing=Boolean(record?.id);const path=`/${endpoints[page]}/${editing?`${record.id}/`:''}`;const hasFile=Object.values(values).some(v=>typeof File!=='undefined'&&v instanceof File);let body=JSON.stringify(values);if(hasFile){body=new FormData();for(const [key,value] of Object.entries(values))body.append(key,value instanceof File?value:String(value));}await api(path,{method:editing?'PATCH':'POST',body});onSaved();}catch(err){setError(err.message);}finally{setBusy(false);}};
  return <div className="modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&onClose()}><form className="modal" onSubmit={submit}><div className="modal-head"><div><span className="eyebrow">TEAM MANAGEMENT</span><h2>{record?.id?'Edit':title}</h2></div><button type="button" className="icon-button" onClick={onClose}><X size={19}/></button></div>{error&&<div className="form-error">{error}</div>}<div className="form-grid">{fields.map(([name,label,type,extra,required])=>type==='hidden'?<input key={name} type="hidden" name={name} value={extra}/>:<label className={type==='textarea'?'full':''} key={name}>{label}{type==='select'?<select name={name} defaultValue={record?.[name]??''} required={Boolean(required ?? (extra===true))}>{extra.map(option=>{const [v,l]=Array.isArray(option)?option:[option,option];return <option key={v} value={v}>{l}</option>;})}</select>:type==='textarea'?<textarea name={name} defaultValue={record?.[name]||''} required={Boolean(required ?? (extra===true))} rows="3"/>:type==='checkbox'?<input className="check-input" name={name} type="checkbox" defaultChecked={record?.[name]??(name==='is_published')}/>:type==='file'?<input name={name} type="file" accept={name==='image_file'?'image/jpeg,image/png,image/webp':'video/mp4,video/webm,video/ogg'}/>:<input name={name} type={type} defaultValue={record?.[name]??''} required={Boolean(required ?? (extra===true))}/>}</label>)}</div><div className="modal-actions"><button type="button" className="secondary-button" onClick={onClose}>Cancel</button><button className="primary-button" disabled={busy}><Plus size={16}/>{busy?'Saving…':record?.id?'Save changes':'Save record'}</button></div></form></div>;
}
function canCreate(page) { return ['Players','Matches','Training','Tournaments','Announcements','Seasons','Team events','Rules & laws','Tactical learning','Video resources','Media gallery','Alumni & supporters','Injury & welfare','News & information'].includes(page); }
function createLabel(page) { return `Add ${({Players:'player',Matches:'match',Training:'session',Tournaments:'tournament',Announcements:'announcement',Seasons:'season','Team events':'event','Rules & laws':'rule resource','Tactical learning':'learning resource','Video resources':'video resource','Media gallery':'media item','Alumni & supporters':'alumni profile','Injury & welfare':'welfare record','News & information':'news story'})[page]||'record'}`; }
function prettyDate(value) { if (!value) return 'Date TBC'; const d = new Date(`${value}T12:00:00`); return new Intl.DateTimeFormat('en-GB',{day:'numeric',month:'short',year:'numeric'}).format(d); }

export default App;
